cat > main.nim << 'EOF'
import std/[asynchttpserver, asyncdispatch, httpclient, json, strformat, os, strutils, times]

# Környezeti kulcsok
let CEREBRAS_API_KEY* = getEnv("CEREBRAS_API_KEY")
let EXA_API_KEY* = getEnv("EXA_API_KEY")
let PORT* = parseInt(getEnv("PORT", "8080"))

if CEREBRAS_API_KEY.len == 0 or EXA_API_KEY.len == 0:
  quit("CEREBRAS_API_KEY és EXA_API_KEY szükséges környezeti változók!", 1)

proc httpJson*(url: string; payload: JsonNode; authBearer: string): Future[JsonNode] {.async.} =
  var client = newAsyncHttpClient()
  defer: client.close()
  client.headers = newHttpHeaders({
    "Content-Type": "application/json",
    "Authorization": "Bearer " & authBearer
  })
  let resp = await client.request(url, httpMethod = HttpPost, body = $payload)
  let body = await resp.body
  if resp.code.int div 100 != 2:
    raise newException(IOError, &"HTTP {resp.code.int}: {body}")
  return parseJson(body)

# Cerebras Chat Completion (nem streamelt, megbízható teljes-válasz)
proc cerebrasChat*(messages: JsonNode; tools: JsonNode = %*[]; toolChoice: string = "auto"; maxTokens = 65000; reasoning = "low"): Future[JsonNode] {.async.} =
  var payload = %*{
    "model": "gpt-oss-120b",
    "messages": messages,
    "max_completion_tokens": maxTokens,
    "temperature": 0.1,
    "top_p": 0.9,
    "stream": false
  }
  if reasoning.len > 0:
    payload["reasoning_effort"] = %*reasoning
  if tools.len > 0:
    payload["tools"] = tools
    payload["tool_choice"] = %*toolChoice
  let url = "https://api.cerebras.ai/v1/chat/completions"
  let res = await httpJson(url, payload, CEREBRAS_API_KEY)
  return res

# Exa Fast keresés (latencia-optimalizált)
proc exaFastSearch*(query: string; numResults = 100): Future[JsonNode] {.async.} =
  var payload = %*{
    "query": query,
    "type": "fast",
    "numResults": numResults,
    "livecrawl": "never"
  }
  let url = "https://api.exa.ai/search"
  let res = await httpJson(url, payload, EXA_API_KEY)
  return res

# LLM-eszköz definíció (OpenAI-style tools -> function schema)
proc exaToolDef*(): JsonNode =
  result = %*[
    {
      "type": "function",
      "function": {
        "name": "exa_search",
        "description": "Gyors, alacsony késleltetésű Exa Fast webkeresés (livecrawl=never), max 100 találat.",
        "parameters": {
          "type": "object",
          "properties": {
            "query": { "type": "string" },
            "numResults": { "type": "integer", "minimum": 1, "maximum": 100 }
          },
          "required": ["query"]
        }
      }
    }
  ]

# Agent kör: a modell kezdeményezhet eszközhívást (exa_search), mi végrehajtjuk és visszaadjuk tool-ként
proc deepResearch*(userQuery: string): Future[string] {.async.} =
  var msgs = %*[
    {"role": "system", "content": "Feladat: Készíts legalább 15 000 szavas, magyar nyelvű, alapos, forrásokra hivatkozó jelentést a felhasználói kérdésről. Használd az elérhető eszközt (exa_search) iteratív webes megalapozáshoz, strukturáld a választ szakaszokkal és egyenletes részletezettséggel. Hivatkozz a forrásokra magyarul, URL-ek feltüntetésével."},
    {"role": "user", "content": userQuery}
  ]

  let tools = exaToolDef()
  # Első hívás, a modell dönthet az eszközről
  var res = await cerebrasChat(msgs, tools=tools, toolChoice="auto", maxTokens=65000, reasoning="low")

  # Kezeljük a tool-callt (ha van)
  # A válasz formátuma a Cerebras OpenAI-szerű struktúráját követi
  var iterations = 0
  var maxIters = 6
  while iterations < maxIters:
    inc iterations
    var choices = res["choices"]
    if choices.len == 0: break
    let msg = choices[0]["message"]
    if msg.hasKey("tool_calls"):
      for tc in msg["tool_calls"].items:
        let fname = tc["function"]["name"].getStr()
        let fargs = tc["function"]["arguments"].getStr()
        if fname == "exa_search":
          var q = ""
          var n = 30
          try:
            let j = parseJson(fargs)
            q = j.getOrDefault("query").getStr()
            if j.hasKey("numResults"): n = j["numResults"].getInt()
          except CatchableError:
            discard
          let exaRes = await exaFastSearch(q, min(max(n,1), 100))
          # A keresési eredményeket bevezetjük tool üzenetként
          msgs.add %*{"role":"tool", "tool_call_id": tc["id"], "name":"exa_search", "content": $exaRes}
      # újrakérdezzük a modellt a friss tool-üzenetekkel
      res = await cerebrasChat(msgs, tools=tools, toolChoice="auto", maxTokens=65000, reasoning="low")
      continue
    else:
      # nincs további tool hívás -> visszaadjuk a végső tartalmat
      if msg.hasKey("content"):
        return msg["content"].getStr()
      break

  # Ha elértük az iter limitet vagy nem jött content
  if res.hasKey("choices") and res["choices"].len > 0:
    return res["choices"][0]["message"].getOrDefault("content").getStr()
  return "Nem sikerült riportot készíteni."

# Egyszerű chat (nem agent)
proc simpleChat*(prompt: string): Future[string] {.async.} =
  let msgs = %*[
    {"role": "system", "content": "Magyar nyelvű, tömör, pontos válaszokat adj."},
    {"role": "user", "content": prompt}
  ]
  let res = await cerebrasChat(msgs, maxTokens=2048, reasoning="low")
  if res.hasKey("choices") and res["choices"].len > 0:
    return res["choices"][0]["message"].getOrDefault("content").getStr()
  return ""

# HTTP szerver
proc handleReq(req: Request) {.async.} =
  try:
    if req.reqMethod == HttpGet and req.url.path == "/":
      await req.respond(Http200, readFile("public/index.html"), newHttpHeaders({"Content-Type":"text/html; charset=utf-8"}))
      return

    if req.reqMethod == HttpPost and req.url.path == "/api/chat":
      let body = await req.body
      let j = parseJson(body)
      let message = j.getOrDefault("message").getStr()
      let reply = await simpleChat(message)
      let out = %*{"reply": reply}
      await req.respond(Http200, $out, newHttpHeaders({"Content-Type":"application/json"}))
      return

    if req.reqMethod == HttpPost and req.url.path == "/api/deepsearch":
      let body = await req.body
      let j = parseJson(body)
      let q = j.getOrDefault("query").getStr()
      let report = await deepResearch(q)
      let out = %*{"report": report}
      await req.respond(Http200, $out, newHttpHeaders({"Content-Type":"application/json"}))
      return

    await req.respond(Http404, "Not found")
  except CatchableError as e:
    let out = %*{"error": e.msg}
    await req.respond(Http500, $out, newHttpHeaders({"Content-Type":"application/json"}))

when isMainModule:
  var server = newAsyncHttpServer()
  echo &"Hallgatózik: http://0.0.0.0:{PORT}/"
  waitFor server.serve(Port(PORT), handleReq)
EOF

