    <script>
      async function ssePost(url, payload, onChunk, onDone, onError) {
        try {
          const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (!res.ok || !res.body) throw new Error('Hálózati hiba: ' + res.status);
          const reader = res.body.getReader();
          const dec = new TextDecoder();
          let buf = '';
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            buf += dec.decode(value, { stream: true });
            const chunks = buf.split('\\n\\n');
            for (let i = 0; i < chunks.length - 1; i++) {
              const line = chunks[i];
              if (line.startsWith('data: ')) onChunk(line.slice(6));
            }
            buf = chunks[chunks.length - 1];
          }
          onDone && onDone();
        } catch (e) { onError && onError(e); }
      }

      // Chat
      const chatInput = document.getElementById('chatInput');
      const chatOut = document.getElementById('chatOut');
      document.getElementById('sendBtn').onclick = () => {
        chatOut.textContent = '';
        ssePost('/api/chat', { message: chatInput.value },
          c => chatOut.textContent += c,
          () => {},
          e => chatOut.innerHTML = '<span class="err">' + e.message + '</span>'
        );
      };

      // Mélykutatás
      const deepQ = document.getElementById('deepQ');
      const deepOut = document.getElementById('deepOut');
      const deepStatus = document.getElementById('deepStatus');
      document.getElementById('deepBtn').onclick = () => {
        deepOut.textContent = '';
        deepStatus.textContent = 'Fut… ez hosszabb ideig tarthat.';
        ssePost('/api/deepsearch', { query: deepQ.value },
          c => deepOut.textContent += c,
          () => deepStatus.textContent = 'Kész.',
          e => deepStatus.innerHTML = '<span class="err">' + e.message + '</span>'
        );
      };
    </script>
