 Telepítő és futtató script
A script letölti a Zig 0.12.x buildet, ellenőrzi a kulcsokat, lefordítja releasefast módban, majd elindítja a szervert a 8080‑as porton [5][4][1].

bash
#!/usr/bin/env bash
set -euo pipefail

# 1) Zig telepítés (ha nincs)
if ! command -v zig >/dev/null 2>&1; then
  echo "[setup] Zig telepítése 0.12.1..."
  ZIG_VER=0.12.1
  ARCH=$(uname -m)
  OS=$(uname -s)
  case "$OS-$ARCH" in
    Linux-x86_64) URL="https://ziglang.org/download/${ZIG_VER}/zig-linux-x86_64-${ZIG_VER}.tar.xz" ;;
    Linux-aarch64) URL="https://ziglang.org/download/${ZIG_VER}/zig-linux-aarch64-${ZIG_VER}.tar.xz" ;;
    Darwin-arm64) URL="https://ziglang.org/download/${ZIG_VER}/zig-macos-aarch64-${ZIG_VER}.tar.xz" ;;
    Darwin-x86_64) URL="https://ziglang.org/download/${ZIG_VER}/zig-macos-x86_64-${ZIG_VER}.tar.xz" ;;
    *) echo "Nem támogatott platform: $OS $ARCH"; exit 1 ;;
  esac
  curl -L "$URL" -o zig.tar.xz
  mkdir -p zigtool && tar -xJf zig.tar.xz -C zigtool --strip-components=1
  export PATH="$PWD/zigtool:$PATH"
fi

# 2) Kötelező env változók
: "${CEREBRAS_API_KEY:?Hiányzik CEREBRAS_API_KEY}"
: "${EXA_API_KEY:?Hiányzik EXA_API_KEY}"

# 3) Build (ReleaseFast)
echo "[build] main.zig fordítása..."
zig build-exe -O ReleaseFast main.zig

# 4) Futás
echo "[run] http://0.0.0.0:8080"
exec ./main



